
'use strict';
const SPECIES=[
{id:'agumon',name:'Agumon',stage:'Rookie',attribute:'Vaccine',field:'Dragons Roar',element:'Fire',attack:'Pepper Breath',color:'#ff9f32',hp:110,speed:185,damage:16,rate:.42},
{id:'gabumon',name:'Gabumon',stage:'Rookie',attribute:'Data',field:'Nature Spirits',element:'Ice',attack:'Blue Blaster',color:'#88c9ed',hp:125,speed:165,damage:17,rate:.50},
{id:'patamon',name:'Patamon',stage:'Rookie',attribute:'Data',field:'Wind Guardians',element:'Air',attack:'Boom Bubble',color:'#f8d07b',hp:95,speed:205,damage:14,rate:.32},
{id:'tentomon',name:'Tentomon',stage:'Rookie',attribute:'Vaccine',field:'Nature Spirits',element:'Electric',attack:'Super Shocker',color:'#e94b52',hp:120,speed:160,damage:19,rate:.55},
{id:'greymon',name:'Greymon',stage:'Champion',attribute:'Vaccine',field:'Dragons Roar',element:'Fire',attack:'Mega Flame',color:'#f58b33',hp:150,speed:145,damage:25,rate:.65},
{id:'garurumon',name:'Garurumon',stage:'Champion',attribute:'Vaccine',field:'Nature Spirits',element:'Ice',attack:'Fox Fire',color:'#9cdbef',hp:130,speed:195,damage:21,rate:.45},
{id:'angemon',name:'Angemon',stage:'Champion',attribute:'Vaccine',field:'Virus Busters',element:'Light',attack:'Heaven Knuckle',color:'#f5eac0',hp:145,speed:170,damage:23,rate:.52},
{id:'devimon',name:'Devimon',stage:'Champion',attribute:'Virus',field:'Nightmare Soldiers',element:'Dark',attack:'Death Claw',color:'#9b85d5',hp:140,speed:180,damage:22,rate:.48},
{id:'metalgreymon',name:'MetalGreymon',stage:'Ultimate',attribute:'Vaccine',field:'Dragons Roar',element:'Fire',attack:'Giga Destroyer',color:'#c87740',hp:165,speed:145,damage:32,rate:.72},
{id:'weregarurumon',name:'WereGarurumon',stage:'Ultimate',attribute:'Vaccine',field:'Nature Spirits',element:'Neutral',attack:'Wolf Claw',color:'#a5c9e8',hp:145,speed:205,damage:27,rate:.46},
{id:'wargreymon',name:'WarGreymon',stage:'Mega',attribute:'Vaccine',field:'Dragons Roar',element:'Fire',attack:'Terra Force',color:'#eab54b',hp:190,speed:175,damage:36,rate:.65},
{id:'metalgarurumon',name:'MetalGarurumon',stage:'Mega',attribute:'Data',field:'Metal Empire',element:'Ice',attack:'Cocytus Breath',color:'#b4c5d5',hp:175,speed:195,damage:33,rate:.54}
];
const STAGES=['Rookie','Champion','Ultimate','Mega','Ultra'],WEIGHTS=[50,30,15,4,1],DUP=[10,25,60,150,400],SAVE_KEY='digimon-survivor-prototype-v2';
const BANNERS=['General','Dragons Roar','Nature Spirits'];
const byId=Object.fromEntries(SPECIES.map(s=>[s.id,s]));
const ELEMENT_COLORS={Fire:'#ff8b38',Ice:'#8be5ff',Air:'#b8ffbd',Electric:'#ffe052',Light:'#fff3a8',Dark:'#b48bff',Neutral:'#f1f5f9'};
const defaults=()=>({tickets:20,coins:0,owned:['agumon'],selected:'agumon',upgrades:{},pity:{},points:{},best:0,runs:0});
function load(){try{const d=JSON.parse(localStorage.getItem(SAVE_KEY));if(!d||typeof d!=='object')return defaults();const v={...defaults(),...d};v.owned=Array.isArray(v.owned)?v.owned.filter(id=>byId[id]):['agumon'];if(!v.owned.length)v.owned=['agumon'];if(!v.owned.includes(v.selected))v.selected=v.owned[0];v.tickets=Math.max(0,Number(v.tickets)||0);v.coins=Math.max(0,Number(v.coins)||0);v.upgrades=v.upgrades||{};v.pity=v.pity||{};v.points=v.points||{};return v;}catch{return defaults();}}
let data=load(),tab='Inicio',banner='General',run=null,keys=new Set(),stick={x:0,y:0},pointer=null,last=0;
const $=id=>document.getElementById(id),save=()=>{try{localStorage.setItem(SAVE_KEY,JSON.stringify(data));}catch{message('No se pudo guardar el progreso.');}},message=s=>{$('status').textContent=s;};
const stageIndex=s=>STAGES.indexOf(s.stage),coinValue=s=>DUP[stageIndex(s)],upgradeLevel=id=>Math.max(0,Math.min(5,Number(data.upgrades[id])||0));
function wallet(){$('wallet').textContent='Tickets '+data.tickets+' · DigiCoins '+data.coins;}
function tabs(){const names=['Inicio','Colección','Gacha','Mejoras','Combate'];$('tabs').innerHTML='';for(const name of names){const b=document.createElement('button');b.textContent=name;b.className=tab===name?'active':'';b.onclick=()=>{if(run&&!run.ended&&name!=='Combate'){run.paused=true;}tab=name;render();};$('tabs').append(b);}}
function card(s,action){const el=document.createElement('div');el.className='card';const h=document.createElement('h3');h.textContent=s.name;h.style.color=s.color;el.append(h);const p=document.createElement('p');p.className='muted';p.textContent=s.stage+' · '+s.attribute+' · '+s.element;el.append(p);const a=document.createElement('p');a.textContent=s.attack;el.append(a);const preview=document.createElement('div');preview.style.cssText='height:54px;display:flex;align-items:center;justify-content:center';preview.innerHTML='<span aria-hidden="true" style="font-size:34px;color:'+s.color+'">◆</span>';el.insertBefore(preview,h);if(action)el.append(action);return el;}
function btn(label,fn,cls=''){const b=document.createElement('button');b.textContent=label;b.className=cls;b.onclick=fn;return b;}
function render(){wallet();tabs();const root=$('content');root.replaceChildren();message('');
if(tab==='Inicio'){root.innerHTML='<section class="panel"><h2>Demo integral v0.5</h2><p>Sobrevive 90 segundos con tu Digimon. Gana tickets y monedas, desbloquea personajes y mejora sus estadísticas.</p><p class="muted">WASD / flechas en PC. En Android, joystick táctil. Ataque automático al enemigo más cercano. Sin digievolución.</p></section>';root.append(btn('Jugar con '+byId[data.selected].name,()=>start(),'primary'));root.append(document.createElement('hr'));const p=document.createElement('p');p.textContent='Mejor tiempo: '+Math.floor(data.best)+'s · Partidas: '+data.runs;root.append(p);}
if(tab==='Colección'){root.innerHTML='<h2>DigiDex ('+data.owned.length+'/'+SPECIES.length+')</h2>';const grid=document.createElement('div');grid.className='cards';for(const s of SPECIES){const owned=data.owned.includes(s.id);const c=card(s,btn(owned?(data.selected===s.id?'Seleccionado':'Seleccionar'):'Bloqueado',()=>{data.selected=s.id;save();render();},owned?'primary':''));c.lastChild.disabled=!owned||data.selected===s.id;grid.append(c);}root.append(grid);}
if(tab==='Mejoras'){root.innerHTML='<h2>Mejoras permanentes</h2><p>+10% HP y +5% daño por nivel (máximo 5). Coste creciente.</p>';const grid=document.createElement('div');grid.className='cards';for(const id of data.owned){const s=byId[id],level=upgradeLevel(id),cost=20*(level+1);const c=card(s,btn(level===5?'Nivel máximo':'Mejorar · '+cost+' DigiCoins',()=>{if(data.coins<cost)return message('DigiCoins insuficientes');data.coins-=cost;data.upgrades[id]=level+1;save();render();},'primary'));c.lastChild.disabled=level>=5||data.coins<cost;const p=document.createElement('p');p.textContent='Nivel '+level+'/5';c.insertBefore(p,c.lastChild);grid.append(c);}root.append(grid);}
if(tab==='Gacha'){root.innerHTML='<h2>Gacha</h2><p>Una tirada cuesta 1 DigiTicket. Duplicados = DigiCoins. Garantía Champion o superior cada 10 tiradas del mismo banner. Cada 30 tiradas: canje por especie del banner.</p>';const nav=document.createElement('div');nav.className='tabs';for(const b of BANNERS)nav.append(btn(b,()=>{banner=b;render();},banner===b?'active':''));root.append(nav);const pool=SPECIES.filter(s=>banner==='General'||s.field===banner);const effective=STAGES.map((st,i)=>pool.some(s=>s.stage===st)?WEIGHTS[i]:0);const sum=effective.reduce((a,b)=>a+b,0);const rate=document.createElement('p');rate.textContent='Tasas efectivas: '+STAGES.filter((_,i)=>effective[i]).map(st=>st+' '+(effective[STAGES.indexOf(st)]/sum*100).toFixed(1)+'%').join(' · ');root.append(rate);const p=document.createElement('p');p.textContent='Pity: '+(data.pity[banner]||0)+'/10 · Puntos: '+(data.points[banner]||0)+'/30';root.append(p);root.append(btn('Invocar ×1',()=>pull(1),'primary'),btn('Invocar ×10',()=>pull(10),'primary'));const h=document.createElement('h3');h.textContent='Canjear 30 puntos';root.append(h);const grid=document.createElement('div');grid.className='cards';for(const s of pool){const c=card(s,btn('Canjear',()=>{if((data.points[banner]||0)<30)return;data.points[banner]-=30;if(data.owned.includes(s.id))data.coins+=coinValue(s);else data.owned.push(s.id);save();render();message('Canje realizado: '+s.name);},''));c.lastChild.disabled=(data.points[banner]||0)<30;grid.append(c);}root.append(grid);}
if(tab==='Combate'){root.innerHTML='<h2>Supervivencia</h2><p id="runHud"></p><div id="gameWrap"><canvas id="game" width="800" height="480"></canvas><div id="stick"><div id="knob"></div></div><div id="levelChoices"></div></div><div class="tabs" style="margin-top:10px" id="runButtons"></div><p class="muted">Mover: WASD, flechas o joystick. Ataque automático. Al subir de nivel, elige una mejora.</p>';setupControls();const actions=$('runButtons');if(!run||run.ended)actions.append(btn('Nueva partida',()=>start(),'primary'));else actions.append(btn(run.paused?'Continuar':'Pausa',()=>{run.paused=!run.paused;draw();},'primary'),btn('Abandonar',()=>finish(false)));draw();}
}
